def _build_component_06():
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(net * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = [[None] + list(rows) for rows in
                   ([sorted(packages[name], key=lambda r: r["version"])
                     for name in names])]
        best_vector = None
        best_versions = None

        for assignment in product(*choices):
            selected = {name: row for name, row in zip(names, assignment)
                        if row is not None}
            versions = {name: row["version"] for name, row in selected.items()}
            valid = True
            for name, (low, high) in roots.items():
                if name not in versions or not low <= versions[name] <= high:
                    valid = False
                    break
            if not valid:
                continue
            if any(version in blocked.get(name, [])
                   for name, version in versions.items()):
                continue
            if any(name in versions and versions[name] != version
                   for name, version in pins.items()):
                continue

            edges = {name: [] for name in selected}
            closure = set(roots)
            stack = list(roots)
            while stack and valid:
                name = stack.pop()
                row = selected.get(name)
                if row is None:
                    valid = False
                    break
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    edges[name].append(target)
                    version = versions.get(target)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    if target not in closure:
                        closure.add(target)
                        stack.append(target)
            if not valid or closure != set(selected):
                continue

            visiting, finished = set(), set()
            def acyclic(name):
                if name in visiting:
                    return False
                if name in finished:
                    return True
                visiting.add(name)
                if any(not acyclic(other) for other in edges.get(name, [])):
                    return False
                visiting.remove(name)
                finished.add(name)
                return True
            if not all(acyclic(name) for name in edges):
                continue

            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start = data["start"]
        initial_mask = bit.get(source, 0)
        coupons = data["coupons"]
        initial = (source, initial_mask, 0)
        dist = {initial: start}
        queue = [(start, source, initial_mask, 0)]
        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and used == coupons:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


